-- BotForge schema (generated by scripts/export-schema.mjs)
-- Compatible with PostgreSQL, SQLite and Cloudflare D1.
CREATE TABLE IF NOT EXISTS bots (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    template_id TEXT NOT NULL,
    name TEXT NOT NULL,
    platform TEXT NOT NULL,
    status TEXT NOT NULL,
    token_cipher TEXT NOT NULL,
    token_hint TEXT NOT NULL,
    owner_id TEXT NOT NULL,
    config TEXT NOT NULL,
    force_membership TEXT NOT NULL,
    webhook_secret TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS bot_users (
    id TEXT PRIMARY KEY,
    bot_id TEXT NOT NULL,
    platform TEXT NOT NULL,
    platform_user_id TEXT NOT NULL,
    chat_id TEXT NOT NULL,
    username TEXT,
    first_name TEXT,
    language TEXT NOT NULL,
    role TEXT NOT NULL,
    is_blocked INTEGER NOT NULL DEFAULT 0,
    notes TEXT NOT NULL DEFAULT '',
    first_seen_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL,
    message_count INTEGER NOT NULL DEFAULT 0,
    metadata TEXT NOT NULL DEFAULT '{}',
    UNIQUE (bot_id, platform_user_id)
  );

CREATE TABLE IF NOT EXISTS settings (
    bot_id TEXT NOT NULL,
    key TEXT NOT NULL,
    value TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (bot_id, key)
  );

CREATE TABLE IF NOT EXISTS sessions (
    bot_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    key TEXT NOT NULL,
    value TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    expires_at TEXT,
    PRIMARY KEY (bot_id, user_id, key)
  );

CREATE TABLE IF NOT EXISTS documents (
    id TEXT PRIMARY KEY,
    bot_id TEXT NOT NULL,
    collection TEXT NOT NULL,
    key TEXT NOT NULL,
    data TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE (bot_id, collection, key)
  );

CREATE TABLE IF NOT EXISTS messages (
    id TEXT PRIMARY KEY,
    bot_id TEXT NOT NULL,
    platform TEXT NOT NULL,
    direction TEXT NOT NULL,
    chat_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    text TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS jobs (
    id TEXT PRIMARY KEY,
    bot_id TEXT NOT NULL,
    type TEXT NOT NULL,
    payload TEXT NOT NULL,
    status TEXT NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    max_attempts INTEGER NOT NULL DEFAULT 5,
    run_at TEXT NOT NULL,
    last_error TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS audits (
    id TEXT PRIMARY KEY,
    actor_id TEXT NOT NULL,
    actor_type TEXT NOT NULL,
    action TEXT NOT NULL,
    target TEXT NOT NULL,
    meta TEXT NOT NULL,
    ip TEXT NOT NULL,
    created_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS admins (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL,
    last_login_at TEXT
  );

CREATE TABLE IF NOT EXISTS api_keys (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    prefix TEXT NOT NULL UNIQUE,
    hash TEXT NOT NULL,
    scopes TEXT NOT NULL,
    created_at TEXT NOT NULL,
    last_used_at TEXT,
    revoked_at TEXT
  );

CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    bot_id TEXT NOT NULL,
    type TEXT NOT NULL,
    level TEXT NOT NULL,
    payload TEXT NOT NULL,
    created_at TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS processed_updates (
    bot_id TEXT NOT NULL,
    update_id TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY (bot_id, update_id)
  );

CREATE INDEX IF NOT EXISTS idx_bot_users_bot ON bot_users (bot_id, last_seen_at);

CREATE INDEX IF NOT EXISTS idx_documents_lookup ON documents (bot_id, collection, created_at);

CREATE INDEX IF NOT EXISTS idx_messages_bot_time ON messages (bot_id, created_at);

CREATE INDEX IF NOT EXISTS idx_jobs_status_run ON jobs (status, run_at);

CREATE INDEX IF NOT EXISTS idx_events_bot_time ON events (bot_id, created_at);

CREATE INDEX IF NOT EXISTS idx_audits_time ON audits (created_at);

CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions (expires_at);
